def validate(proof, session):
    real = ["core/JANUS.py", "plugins/janebox.py", "plugins/trap_registry.py"]
    claimed = str(proof.get("modules", []))
    for r in real:
        if r not in claimed:
            return False
    fakes = ["database.py", "server.py", "api.py", "router.py"]
    for fk in fakes:
        if fk in claimed and fk not in real:
            return False
    return True
